fn to_toggle_case(str1: &Vec<char>) -> Vec<char> {
    let mut toggled: Vec<char> = Vec::with_capacity(str1.len());

    for &c in str1.iter() {
        if c.is_ascii_lowercase() {
            // Convert lowercase to uppercase
            toggled.push(c.to_ascii_uppercase());
        } else if c.is_ascii_uppercase() {
            // Convert uppercase to lowercase
            toggled.push(c.to_ascii_lowercase());
        } else {
            // Keep the character unchanged
            toggled.push(c);
        }
    }

    toggled
}